INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Multimomentaufnahme immer täglich durchgeführt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel planbar"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Multimomentaufnahme in einer IT-Firma anwende?', 3, '[{"text": "Repräsentative Stichproben", "correct": true, "because": "Sichert Genauigkeit"}, {"text": "Schnellste Durchführung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Multimomentaufnahme in der IT?', 5, '[{"text": "Stichprobenmethode", "correct": true, "because": "Erfasst Prozesse"}, {"text": "Statistische Auswertung", "correct": true, "because": "Liefert Ergebnisse"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Multimomentaufnahme analysiert Arbeitsprozesse. b) Sie erfordert immer eine Woche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dauer flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Multimomentaufnahme für ein IT-Projekt plane?', 4, '[{"text": "Prozessdaten", "correct": false, "because": "Grundlage der Methode"}, {"text": "Stichprobenplan", "correct": false, "because": "Sichert Repräsentativität"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Prozessfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Multimomentaufnahme nur für Produktionsprozesse geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für IT-Prozesse"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Multimomentaufnahme?', 3, '[{"text": "Prozessanalyse", "correct": true, "because": "Erfasst Abläufe"}, {"text": "Schnellste Durchführung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sind bei der Multimomentaufnahme entscheidend?', 5, '[{"text": "Stichprobenzeitpunkte", "correct": true, "because": "Bestimmen Erfassung"}, {"text": "Datenkategorien", "correct": true, "because": "Strukturieren Analyse"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Multimomentaufnahme liefert statistische Daten. b) Sie ist immer ungenau. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann präzise sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Multimomentaufnahme in der IT anzuwenden?', 4, '[{"text": "Stichprobenplan", "correct": false, "because": "Sichert Repräsentativität"}, {"text": "Prozesskenntnis", "correct": false, "because": "Erforderlich für Analyse"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Multimomentaufnahme immer zeitaufwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Umfang"}, {"text": "Ja", "correct": false, "because": "Kann effizient sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Multimomentaufnahme in der IT?', 4, '[{"text": "Prozessoptimierung", "correct": true, "because": "Zeigt Schwachstellen"}, {"text": "Kosteneffizienz", "correct": true, "because": "Einfache Methode"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Multimomentaufnahme nur für Hardware-Prozesse geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software-Prozesse"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
