('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Multimomentaufnahme?', 5, '[{"text": "Stichprobengröße", "correct": true, "because": "Beeinflusst Genauigkeit"}, {"text": "Prozesskategorien", "correct": true, "because": "Strukturieren Daten"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Multimomentaufnahme plane?', 3, '[{"text": "Zeitpunkte", "correct": false, "because": "Bestimmen Erfassung"}, {"text": "Datenanalyse", "correct": false, "because": "Liefert Ergebnisse"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Prozessfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Multimomentaufnahme immer für alle Prozesse geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Komplexität"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
